SELECT trpm.dept_name AS dept_name_p, trpm.position_title AS position_title, trpm.position_code AS position_code, trpm.position_owner AS position_owner, trpm.position_date_created AS position_date_created, trpm.position_date_expiry AS position_date_expiry FROM  tp_cr_position_master  as trpm JOIN  tp_cr_position_status_summary  as trps on (trpm.position_id = trps.position_id) WHERE 1 